const OtherCash=()=>{const [rows,setRows]=useState<FinanceRow[]>([]);const load=()=>void listFinance().then(setRows);useEffect(load,[]);return <Panel title="Transaksi Lain"><p className="text-sm text-black/50 mb-4">Transaksi production dibaca dari buku keuangan canonical. Pemasukan berasal dari pembayaran invoice; pengeluaran dicatat melalui menu Keuangan.</p><Table head={['Tanggal','Referensi','Jenis','Kategori','Keterangan','Jumlah']}>{rows.map(r=><tr key={r.id} className="border-t border-black/[.06] hover:bg-black/[.018]"><Td>{r.entry_date}</Td><Td>{r.reference_no||'—'}</Td><Td>{r.type==='income'?'Pemasukan':'Pengeluaran'}</Td><Td>{r.category}</Td><Td>{r.description}</Td><Td>{money(r.amount)}</Td></tr>)}</Table></Panel>};
const ExpenseEntryForm=({onDone}:{onDone:()=>void})=>{const [date,setDate]=useState(new Date().toISOString().slice(0,10)),[category,setCategory]=useState('Operasional'),[description,setDescription]=useState(''),[amount,setAmount]=useState(''),[reference,setReference]=useState(''),[receipt,setReceipt]=useState<File|null>(null),[busy,setBusy]=useState(false),[error,setError]=useState('');return <form className="border rounded-xl p-4 mb-4 grid md:grid-cols-2 gap-3" onSubmit={async e=>{e.preventDefault();if(!receipt){setError('Bukti pengeluaran wajib diunggah.');return}setBusy(true);setError('');try{await addFinance({entry_date:date,type:'expense',category,description,amount:Number(amount),reference_no:reference||null,receipt});onDone()}catch(e){setError(e instanceof Error?e.message:'Gagal mencatat pengeluaran.')}finally{setBusy(false)}}}><input required type="date" className="field" value={date} onChange={e=>setDate(e.target.value)}/><input required className="field" placeholder="Kategori" value={category} onChange={e=>setCategory(e.target.value)}/><input required className="field md:col-span-2" placeholder="Keterangan pengeluaran" value={description} onChange={e=>setDescription(e.target.value)}/><input required type="number" min="1" className="field" placeholder="Nominal" value={amount} onChange={e=>setAmount(e.target.value)}/><input className="field" placeholder="Referensi (opsional)" value={reference} onChange={e=>setReference(e.target.value)}/><label className="text-xs font-semibold md:col-span-2">Bukti pengeluaran<input required type="file" className="field w-full mt-1" onChange={e=>setReceipt(e.target.files?.[0]||null)}/></label><button disabled={busy} className="btn justify-center md:col-span-2">{busy?'Menyimpan...':'Catat Pengeluaran'}</button>{error&&<p className="text-xs text-red-600 md:col-span-2">{error}</p>}</form>};
export const FinanceModule=({permissionKeys=[]}:{permissionKeys?:string[]})=>{const [rows,setRows]=useState<FinanceRow[]>([]);const [open,setOpen]=useState(false);const load=()=>void listFinance().then(setRows);useEffect(load,[]);const income=rows.filter(x=>x.type==='income').reduce((a,b)=>a+b.amount,0),expense=rows.filter(x=>x.type==='expense').reduce((a,b)=>a+b.amount,0);return <div className="space-y-4"><div className="grid sm:grid-cols-3 gap-4">{[['Pemasukan',income],['Pengeluaran',expense],['Saldo',income-expense]].map(([l,v])=><div className="bg-white border border-black/[.08] rounded-[20px] shadow-[0_1px_2px_rgba(0,0,0,.02)] p-5" key={String(l)}><p className="text-xs text-black/50">{l}</p><p className="font-bold text-xl mt-2">{money(Number(v))}</p></div>)}</div><Panel title="Buku Keuangan" action={permissionKeys.includes('finance_expenses.record')?<button onClick={()=>setOpen(!open)} className="btn"><Plus size={14}/>Catat Pengeluaran</button>:undefined}>{open&&<ExpenseEntryForm onDone={()=>{setOpen(false);load()}}/>}<Table head={['Tanggal','Jenis','Kategori','Keterangan','Jumlah']}>{rows.map(r=><tr key={r.id} className="border-t border-black/[.06] hover:bg-black/[.018]"><Td>{r.entry_date}</Td><Td>{r.type}</Td><Td>{r.category}</Td><Td>{r.description}</Td><Td>{money(r.amount)}</Td></tr>)}</Table></Panel></div>};
export const ReportsModule=({permissionKeys=[]}:{permissionKeys?:string[]})=>{const [data,setData]=useState<any>(null),[error,setError]=useState('');const [periods,setPeriods]=useState<FinancialPeriodRow[]>([]);const [year,setYear]=useState(String(new Date().getFullYear())),[month,setMonth]=useState(String(new Date().getMonth()+1)),[busy,setBusy]=useState(false);const loadPeriods=()=>void listFinancialPeriods().then(setPeriods).catch(e=>setError(e instanceof Error?e.message:'Gagal memuat periode.'));useEffect(()=>{void getSalesReport().then(setData).catch(e=>setError(e instanceof Error?e.message:'Gagal memuat laporan.'));loadPeriods()},[]);return <div className="space-y-4"><Panel title="Periode Laporan Bulanan">{permissionKeys.includes('financial_periods.create')&&<div className="flex flex-wrap gap-2 mb-4"><input className="field w-28" type="number" min="2024" max="2100" value={year} onChange={e=>setYear(e.target.value)}/><select className="field" value={month} onChange={e=>setMonth(e.target.value)}>{Array.from({length:12},(_,i)=><option key={i+1} value={i+1}>{new Date(2026,i,1).toLocaleString('id-ID',{month:'long'})}</option>)}</select><button disabled={busy} className="btn" onClick={async()=>{setBusy(true);setError('');try{await createMonthlyFinancialPeriod(Number(year),Number(month));loadPeriods()}catch(e){setError(e instanceof Error?e.message:'Gagal membuat periode.')}finally{setBusy(false)}}}>Buat Periode Bulanan</button></div>}<Table head={['Periode','Tanggal','Status','Aksi']}>{periods.map(p=><tr key={p.id} className="border-t"><Td>{p.period_type==='monthly'?new Date(p.starts_on+'T00:00:00').toLocaleString('id-ID',{month:'long',year:'numeric'}):p.period_type}</Td><Td>{p.starts_on} — {p.ends_on}</Td><Td>{p.status}</Td><Td>{p.status==='open'&&permissionKeys.includes('financial_periods.close')?<button className="border rounded-lg px-2 py-1 text-xs font-semibold" onClick={async()=>{setBusy(true);setError('');try{await closeFinancialPeriod(p.id);loadPeriods()}catch(e){setError(e instanceof Error?e.message:'Periode belum dapat ditutup.')}finally{setBusy(false)}}}>Tutup Periode</button>:<span className="text-xs text-black/40">—</span>}</Td></tr>)}</Table></Panel><FinancialReportsPanel periods={periods} permissionKeys={permissionKeys}/><ProfitDistributionsPanel permissionKeys={permissionKeys}/><Panel title="Laporan Keuangan & Penjualan">{error&&<p className="text-sm text-red-600 mb-4">{error}</p>}<div className="grid sm:grid-cols-2 xl:grid-cols-4 gap-4"><Stat l="Omzet Invoice" v={data?money(data.total):'—'}/><Stat l="Pemasukan Terkonfirmasi" v={data?money(data.income):'—'}/><Stat l="Refund" v={data?money(data.refund):'—'}/><Stat l="Pengeluaran" v={data?money(data.expense):'—'}/><Stat l="Kas Bersih" v={data?money(data.netCash):'—'}/><Stat l="Sisa Tagihan" v={data?money(data.outstanding):'—'}/><Stat l="Total Pax" v={data?String(data.pax):'—'}/><Stat l="DP / Lunas" v={data?`${data.partial} / ${data.paid}`:'—'}/></div><p className="text-sm text-black/50 mt-6">Angka laporan menggunakan sumber canonical yang sama dengan Kasir dan Ringkasan: invoice, item/pax, pembayaran confirmed, refund processed, dan pengeluaran production.</p></Panel></div>};

const FinancialReportsPanel=({periods,permissionKeys}:{periods:FinancialPeriodRow[];permissionKeys:string[]})=>{const [rows,setRows]=useState<FinancialReportRow[]>([]),[periodId,setPeriodId]=useState(''),[title,setTitle]=useState(''),[edit,setEdit]=useState<FinancialReportRow|null>(null),[busy,setBusy]=useState(false),[error,setError]=useState('');const load=()=>void listFinancialReports().then(setRows).catch(e=>setError(e instanceof Error?e.message:'Gagal memuat laporan keuangan.'));useEffect(load,[]);const act=async(id:string,target:'review'|'approved'|'published')=>{setBusy(true);setError('');try{await transitionFinancialReport(id,target);load()}catch(e){setError(e instanceof Error?e.message:'Transisi laporan gagal.')}finally{setBusy(false)}};return <Panel title="Laporan Bulanan Canonical">{permissionKeys.includes('financial_reports.create')&&<div className="grid md:grid-cols-[1fr_2fr_auto] gap-2 mb-4"><select className="field" value={periodId} onChange={e=>setPeriodId(e.target.value)}><option value="">Pilih periode</option>{periods.filter(p=>p.period_type==='monthly').map(p=><option key={p.id} value={p.id}>{p.starts_on} — {p.ends_on} · {p.status}</option>)}</select><input className="field" placeholder="Judul laporan, contoh: Laporan September 2026" value={title} onChange={e=>setTitle(e.target.value)}/><button className="btn" disabled={busy||!periodId||!title.trim()} onClick={async()=>{setBusy(true);setError('');try{await createFinancialReportDraft({periodId,title:title.trim(),visibility:'investors',source:'internal'});setTitle('');load()}catch(e){setError(e instanceof Error?e.message:'Gagal membuat draft laporan.')}finally{setBusy(false)}}}>Buat Draft</button></div>}<Table head={['Laporan','Status','Aksi']}>{rows.map(r=><tr key={r.id} className="border-t"><Td><b>{r.title}</b><div className="text-xs text-black/45">{periods.find(p=>p.id===r.financial_period_id)?.starts_on||'—'} — {periods.find(p=>p.id===r.financial_period_id)?.ends_on||'—'}</div></Td><Td>{r.status}</Td><Td><div className="flex flex-wrap gap-2">{r.status==='draft'&&permissionKeys.includes('financial_reports.update')&&<button className="border rounded-lg px-2 py-1 text-xs" onClick={()=>setEdit(r)}>Isi Laporan</button>}{r.status==='draft'&&permissionKeys.includes('financial_reports.review')&&<button className="border rounded-lg px-2 py-1 text-xs" onClick={()=>act(r.id,'review')}>Kirim Review</button>}{r.status==='review'&&permissionKeys.includes('financial_reports.approve')&&<button className="border rounded-lg px-2 py-1 text-xs" onClick={()=>act(r.id,'approved')}>Setujui</button>}{r.status==='approved'&&permissionKeys.includes('financial_reports.publish')&&<button className="border rounded-lg px-2 py-1 text-xs" onClick={()=>act(r.id,'published')}>Publish</button>}</div></Td></tr>)}</Table>{edit&&<FinancialReportEditor report={edit} onClose={()=>setEdit(null)} onDone={()=>{setEdit(null);load()}}/>}{error&&<p className="text-xs text-red-600 mt-3">{error}</p>}<p className="text-xs text-black/45 mt-3">Review hanya akan diterima database setelah lampiran, line item keuangan, dan KPI laporan lengkap. Publish hanya dapat dilakukan setelah periode ditutup dan tanggal akhir periode telah lewat.</p></Panel>};

const FinancialReportEditor=({report,onClose,onDone}:{report:FinancialReportRow;onClose:()=>void;onDone:()=>void})=>{const [revenue,setRevenue]=useState(0),[expense,setExpense]=useState(0),[refund,setRefund]=useState(0),[payments,setPayments]=useState(0),[pax,setPax]=useState(0),[file,setFile]=useState<File|null>(null),[busy,setBusy]=useState(false),[error,setError]=useState('');useEffect(()=>{void getFinancialReportCashReconciliation(report.id).then(r=>{setRevenue(Number(r.net_receipts||0));setExpense(Number(r.recorded_expenses||0));setRefund(Number(r.processed_refunds||0));setPayments(Number(r.confirmed_payments||0))}).catch(e=>setError(e instanceof Error?e.message:'Gagal memuat rekonsiliasi kas.'));void getFinancialReportOperationalReconciliation(report.id).then(r=>setPax(Number(r.canonical_pax||0))).catch(e=>setError(e instanceof Error?e.message:'Gagal memuat rekonsiliasi pax.'))},[report.id]);return <div className="fixed inset-0 z-50 bg-black/40 flex items-center justify-center p-4"><form className="bg-white rounded-2xl p-6 w-full max-w-lg" onSubmit={async e=>{e.preventDefault();if(!file){setError('Lampiran PDF wajib diunggah.');return}setBusy(true);setError('');try{await getFinancialReportCashReconciliation(report.id).then(r=>{setRevenue(Number(r.net_receipts||0));setExpense(Number(r.recorded_expenses||0));if(Number(r.net_receipts||0)!==revenue||Number(r.recorded_expenses||0)!==expense)throw new Error('Data kas berubah. Nilai rekonsiliasi telah diperbarui; periksa kembali sebelum menyimpan.')});await getFinancialReportOperationalReconciliation(report.id).then(r=>{if(Number(r.canonical_pax||0)!==pax){setPax(Number(r.canonical_pax||0));throw new Error('Data pax berubah. Nilai canonical telah diperbarui; periksa kembali sebelum menyimpan.')}});const assetId=await uploadFinancialReportAttachment(file);await saveFinancialReportContent({reportId:report.id,documentAssetId:assetId,revenue,expense,pax});onDone()}catch(e){setError(e instanceof Error?e.message:'Gagal menyimpan laporan.')}finally{setBusy(false)}}}><div className="flex justify-between gap-3"><div><h3 className="font-bold">Isi Laporan Bulanan</h3><p className="text-xs text-black/45 mt-1">{report.title}</p></div><button type="button" onClick={onClose}><X size={18}/></button></div><div className="grid grid-cols-2 gap-3 mt-5"><Stat l="Pembayaran Confirmed" v={money(payments)}/><Stat l="Refund Processed" v={money(refund)}/><Stat l="Pendapatan Bersih Canonical" v={money(revenue)}/><Stat l="Pengeluaran Recorded" v={money(expense)}/></div><div className="space-y-3 mt-4"><p className="text-xs text-black/45">Pendapatan dan pengeluaran dihitung otomatis dari Kasir dan buku keuangan untuk periode laporan; tidak dapat diinput manual.</p><Stat l="Total Pax Canonical" v={String(pax)}/><label className="block text-xs font-semibold">Lampiran laporan PDF<input required type="file" accept="application/pdf,.pdf" className="field w-full mt-1" onChange={e=>setFile(e.target.files?.[0]||null)}/></label><button disabled={busy} className="btn justify-center w-full">{busy?'Menyimpan...':'Simpan Isi Laporan'}</button>{error&&<p className="text-xs text-red-600">{error}</p>}</div></form></div>};

const DistributionPayoutBox=({distributionId,permissionKeys}:{distributionId:string;permissionKeys:string[]})=>{const [rows,setRows]=useState<any[]>([]),[error,setError]=useState(''),[busy,setBusy]=useState('');const load=()=>void listProfitDistributionAllocations(distributionId).then(setRows).catch(e=>setError(e instanceof Error?e.message:'Gagal memuat alokasi.'));useEffect(load,[distributionId]);return <div className="mt-3 border rounded-xl p-3"><Table head={['Investor','Alokasi','Status','Referensi','Aksi']}>{rows.map(r=><tr key={r.id} className="border-t"><Td><span className="text-xs">{r.investor_id}</span></Td><Td>{money(r.allocation_amount)}</Td><Td>{r.status}</Td><Td>{r.payment_reference||'—'}</Td><Td><div className="flex flex-wrap gap-2">{r.status==='payable'&&permissionKeys.includes('profit_distribution_payments.upload_proof')&&<label className="border rounded-lg px-2 py-1 text-xs cursor-pointer">Upload Bukti<input type="file" className="hidden" accept=".pdf,image/jpeg,image/png,image/webp" disabled={!!busy} onChange={async e=>{const file=e.target.files?.[0];if(!file)return;const ref=window.prompt('Masukkan referensi pembayaran/transfer:')?.trim();if(!ref)return;setBusy(r.id);setError('');try{await uploadProfitDistributionProof(r,file,ref);load()}catch(e){setError(e instanceof Error?e.message:'Upload bukti gagal.')}finally{setBusy('');e.target.value=''}}}/></label>}{r.status==='payable'&&permissionKeys.includes('profit_distribution_payments.mark_paid')&&<button disabled={!!busy} className="border rounded-lg px-2 py-1 text-xs" onClick={async()=>{setBusy(r.id);setError('');try{await markProfitDistributionAllocationPaid(r.id);load()}catch(e){setError(e instanceof Error?e.message:'Mark paid ditolak.')}finally{setBusy('')}}}>Tandai Paid</button>}{r.status==='paid'&&<span className="text-xs text-black/50">Paid {r.paid_at?new Date(r.paid_at).toLocaleString('id-ID'):''}</span>}</div></Td></tr>)}</Table>{error&&<p className="text-xs text-red-600 mt-2">{error}</p>}<p className="text-xs text-black/45 mt-2">Database menerapkan dual-control: creator/approver/uploader bukti tidak dapat menandai payout yang sama sebagai paid, kecuali Super Admin.</p></div>};

const ProfitDistributionsPanel=({permissionKeys}:{permissionKeys:string[]})=>{const [rows,setRows]=useState<ProfitDistributionRow[]>([]),[reports,setReports]=useState<FinancialReportRow[]>([]),[offerings,setOfferings]=useState<any[]>([]),[reportVersion,setReportVersion]=useState(''),[offering,setOffering]=useState(''),[expanded,setExpanded]=useState(''),[busy,setBusy]=useState(false),[error,setError]=useState('');const load=()=>{void listProfitDistributions().then(setRows).catch(e=>setError(e instanceof Error?e.message:'Gagal memuat distribusi.'));void listFinancialReports().then(setReports);void supabase?.from('ownership_offerings').select('id,title,status').eq('status','open').then(({data})=>setOfferings(data||[]))};useEffect(load,[]);const act=async(id:string,target:'review'|'approved'|'payable')=>{setBusy(true);setError('');try{await transitionProfitDistribution(id,target);load()}catch(e){setError(e instanceof Error?e.message:'Transisi distribusi gagal.')}finally{setBusy(false)}};return <Panel title="Distribusi Hasil Investor">{permissionKeys.includes('profit_distributions.create')&&<div className="grid md:grid-cols-[2fr_2fr_auto] gap-2 mb-4"><select className="field" value={reportVersion} onChange={e=>setReportVersion(e.target.value)}><option value="">Laporan published</option>{reports.filter(r=>r.status==='published'&&r.published_version_id).map(r=><option key={r.id} value={r.published_version_id!}>{r.title}</option>)}</select><select className="field" value={offering} onChange={e=>setOffering(e.target.value)}><option value="">Offering</option>{offerings.map(o=><option key={o.id} value={o.id}>{o.title||o.id}</option>)}</select><button className="btn" disabled={busy||!reportVersion||!offering} onClick={async()=>{setBusy(true);setError('');try{await createProfitDistribution(reportVersion,offering);load()}catch(e){setError(e instanceof Error?e.message:'Gagal membuat distribusi.')}finally{setBusy(false)}}}>Buat Distribusi</button></div>}<Table head={['Periode','Profit','Pool Investor','Status','Audit','Aksi']}>{rows.map(r=><Fragment key={r.id}><tr className="border-t"><Td>{r.period_start} — {r.period_end}</Td><Td>{money(r.profit_amount)}</Td><Td>{money(r.investor_pool_amount)} <div className="text-xs text-black/40">{(r.investor_pool_bps/100).toFixed(2)}%</div></Td><Td>{r.status}</Td><Td><div className="text-[10px] text-black/45">Creator: {r.created_by||'—'}<br/>Approver: {r.approved_by||'—'}<br/>Release: {r.payable_by||'—'}</div></Td><Td><div className="flex flex-wrap gap-2">{['draft','review'].includes(r.status)&&permissionKeys.includes('profit_distributions.update')&&<button className="border rounded-lg px-2 py-1 text-xs" onClick={async()=>{setBusy(true);try{await regenerateProfitAllocations(r.id);load()}catch(e){setError(e instanceof Error?e.message:'Gagal membuat alokasi.')}finally{setBusy(false)}}}>Generate Alokasi</button>}{r.status==='draft'&&permissionKeys.includes('profit_distributions.update')&&<button className="border rounded-lg px-2 py-1 text-xs" onClick={()=>act(r.id,'review')}>Review</button>}{r.status==='review'&&permissionKeys.includes('profit_distributions.approve')&&<button className="border rounded-lg px-2 py-1 text-xs" onClick={()=>act(r.id,'approved')}>Setujui</button>}{r.status==='approved'&&permissionKeys.includes('profit_distributions.publish')&&<button className="border rounded-lg px-2 py-1 text-xs" onClick={()=>act(r.id,'payable')}>Release Payable</button>}{['payable','paid'].includes(r.status)&&<button className="border rounded-lg px-2 py-1 text-xs" onClick={()=>setExpanded(expanded===r.id?'':r.id)}>{expanded===r.id?'Tutup Payout':'Lihat Payout'}</button>}</div></Td></tr>{expanded===r.id&&<tr><td colSpan={6}><DistributionPayoutBox distributionId={r.id} permissionKeys={permissionKeys}/></td></tr>}</Fragment>)}</Table>{error&&<p className="text-xs text-red-600 mt-3">{error}</p>}<p className="text-xs text-black/45 mt-3">Nilai profit dan pool investor berasal dari snapshot laporan published. Alokasi dihitung dari riwayat kepemilikan pada cutoff periode. Approval, release, proof, dan payout diaudit terpisah.</p></Panel>};

export const DocumentsModule=({permissionKeys=[],roleLabel=''}:{permissionKeys?:string[];roleLabel?:string})=>{const canCreate=permissionKeys.includes('documents.create');const canReview=permissionKeys.includes('documents.review');const canApprove=permissionKeys.includes('documents.approve');const canPublish=permissionKeys.includes('documents.publish');const canArchive=permissionKeys.includes('documents.archive');const canAssign=permissionKeys.includes('investor_documents.assign');const canRevoke=permissionKeys.includes('investor_documents.revoke');const isSuper=/super admin/i.test(roleLabel);const [rows,setRows]=useState<DocumentRow[]>([]),[open,setOpen]=useState(false),[grantDoc,setGrantDoc]=useState<DocumentRow|null>(null),[currentUserId,setCurrentUserId]=useState(''),[busy,setBusy]=useState(''),[error,setError]=useState('');const load=()=>void listDocuments().then(setRows).catch(e=>setError(e instanceof Error?e.message:'Gagal memuat dokumen.'));useEffect(()=>{load();void supabase?.auth.getUser().then(({data})=>setCurrentUserId(data.user?.id||''))},[]);const act=async(r:DocumentRow,target:'review'|'approved'|'published'|'archived')=>{setBusy(r.id+target);setError('');try{await transitionDocument(r.id,target);load()}catch(e){setError(e instanceof Error?e.message:'Transisi dokumen ditolak.')}finally{setBusy('')}};return <Panel title="Dokumen Portal" action={canCreate?<button onClick={()=>setOpen(!open)} className="btn"><Plus size={14}/>Upload PDF</button>:undefined}>{open&&canCreate&&<DocumentForm onDone={()=>{setOpen(false);load()}}/>}<Table head={['Judul','Kategori','Akses','Status','Audit','Aksi']}>{rows.map(r=>{const selfCreator=!!currentUserId&&r.version_created_by===currentUserId,selfApprover=!!currentUserId&&r.approved_by===currentUserId;return <tr key={r.id} className="border-t border-black/[.06] hover:bg-black/[.018]"><Td><span className="font-semibold">{r.title}</span></Td><Td>{r.category}</Td><Td>{r.audience}</Td><Td><span className="capitalize">{r.status}</span></Td><Td><div className="text-[10px] leading-4 text-black/45">Creator: {r.version_created_by||'—'}<br/>Approver: {r.approved_by||'—'}{r.approved_at?<><br/>{new Date(r.approved_at).toLocaleString('id-ID')}</>:null}</div></Td><Td><div className="flex flex-wrap gap-2">{canReview&&r.status==='draft'&&<button disabled={!!busy} className="border rounded-lg px-2 py-1 text-xs" onClick={()=>act(r,'review')}>Kirim Review</button>}{canApprove&&r.status==='review'&&(isSuper||!selfCreator)&&<button disabled={!!busy} className="border rounded-lg px-2 py-1 text-xs" onClick={()=>act(r,'approved')}>Setujui</button>}{canApprove&&r.status==='review'&&!isSuper&&selfCreator&&<span className="text-[10px] text-black/40">Menunggu approver lain</span>}{canPublish&&r.status==='approved'&&(isSuper||(!selfApprover&&!!r.approved_by))&&<button disabled={!!busy} className="border rounded-lg px-2 py-1 text-xs" onClick={()=>act(r,'published')}>Publish</button>}{canPublish&&r.status==='approved'&&!isSuper&&(selfApprover||!r.approved_by)&&<span className="text-[10px] text-black/40">{!r.approved_by?'Perlu approval ulang':'Menunggu publisher lain'}</span>}{canArchive&&r.status==='published'&&<button disabled={!!busy} className="border rounded-lg px-2 py-1 text-xs" onClick={()=>act(r,'archived')}>Arsipkan</button>}{canAssign&&r.audience==='restricted'&&<button className="border rounded-lg px-2 py-1 text-xs" onClick={()=>setGrantDoc(r)}>Atur Investor</button>}</div></Td></tr>})}</Table>{error&&<p className="text-xs text-red-600 mt-3">{error}</p>}<p className="text-xs text-black/45 mt-3">Workflow wajib terpisah: draft/review → approval → publication. Creator tidak dapat menyetujui versinya sendiri dan approver tidak dapat mem-publish versi yang sama, kecuali Super Admin.</p>{grantDoc&&<DocumentGrantBox doc={grantDoc} canAssign={canAssign} canRevoke={canRevoke} onClose={()=>setGrantDoc(null)}/>}</Panel>};
const DocumentForm=({onDone}:{onDone:()=>void})=>{const [title,setTitle]=useState(''),[category,setCategory]=useState('supporting'),[audience,setAudience]=useState<'public'|'investor'|'restricted'|'internal'>('public'),[file,setFile]=useState<File|null>(null),[busy,setBusy]=useState(false),[error,setError]=useState('');return <form onSubmit={async e=>{e.preventDefault();if(!file)return;setBusy(true);setError('');try{await uploadPortalDocument({file,title,category,audience,published:false});onDone()}catch(err){setError(err instanceof Error?err.message:'Upload gagal.')}finally{setBusy(false)}}} className="grid md:grid-cols-5 gap-3 p-4 mb-5 bg-black/[.025] rounded-xl"><input required className="field border-black/[.10] bg-white outline-none focus:ring-2 focus:ring-black/10" placeholder="Judul dokumen" value={title} onChange={e=>setTitle(e.target.value)}/><select className="field border-black/[.10] bg-white outline-none focus:ring-2 focus:ring-black/10" value={category} onChange={e=>setCategory(e.target.value)}><option value="investment_proposal">Proposal Investasi</option><option value="pitch_deck">Pitch Deck</option><option value="investor_report">Laporan Investor</option><option value="business_update">Pembaruan Bisnis</option><option value="supporting">Dokumen Pendukung</option></select><select className="field border-black/[.10] bg-white outline-none focus:ring-2 focus:ring-black/10" value={audience} onChange={e=>setAudience(e.target.value as 'public'|'investor'|'restricted'|'internal')}><option value="public">Publik</option><option value="investor">Semua Investor</option><option value="restricted">Investor Tertentu</option><option value="internal">Internal</option></select><input required className="field border-black/[.10] bg-white outline-none focus:ring-2 focus:ring-black/10" type="file" accept="application/pdf,.pdf" onChange={e=>setFile(e.target.files?.[0]||null)}/><button disabled={busy} className="btn justify-center">{busy?'Mengunggah...':'Upload Draft'}</button>{error&&<p className="md:col-span-5 text-xs text-red-600">{error}</p>}</form>};
const DocumentGrantBox=({doc,canAssign,canRevoke,onClose}:{doc:DocumentRow;canAssign:boolean;canRevoke:boolean;onClose:()=>void})=>{const [investors,setInvestors]=useState<InvestorRow[]>([]),[grants,setGrants]=useState<any[]>([]),[investor,setInvestor]=useState(''),[error,setError]=useState('');const load=()=>{void listInvestors().then(setInvestors);void listDocumentGrants(doc.id).then(setGrants).catch(e=>setError(e instanceof Error?e.message:'Gagal memuat akses.'))};useEffect(load,[doc.id]);return <div className="fixed inset-0 z-50 bg-black/40 flex items-center justify-center p-4"><div className="bg-white rounded-2xl p-6 w-full max-w-lg"><div className="flex justify-between"><div><h3 className="font-bold">Akses Investor</h3><p className="text-xs text-black/45 mt-1">{doc.title}</p></div><button onClick={onClose}><X size={18}/></button></div>{canAssign&&<div className="flex gap-2 my-5"><select className="field flex-1" value={investor} onChange={e=>setInvestor(e.target.value)}><option value="">Pilih investor</option>{investors.filter(i=>['approved','active'].includes(i.status)).map(i=><option key={i.user_id} value={i.user_id}>{i.investor_code||'—'} · {i.full_name}</option>)}</select><button className="btn" disabled={!investor} onClick={async()=>{try{await grantDocumentToInvestor(doc.id,investor);setInvestor('');load()}catch(e){setError(e instanceof Error?e.message:'Gagal memberi akses.')}}}>Berikan</button></div>}<div className="space-y-2">{grants.map((g:any)=>{const inv=Array.isArray(g.investors)?g.investors[0]:g.investors;return <div key={g.id} className="border rounded-xl p-3 flex justify-between gap-3"><div className="text-sm"><b>{inv?.legal_name||g.investor_id}</b><div className="text-xs text-black/45">{inv?.reference_code||'—'} · {g.revoked_at?'Dicabut':'Aktif'}</div></div>{canRevoke&&!g.revoked_at&&<button className="text-xs text-red-700" onClick={async()=>{await revokeDocumentGrant(g.id);load()}}>Cabut</button>}</div>})}</div>{error&&<p className="text-xs text-red-600 mt-3">{error}</p>}</div></div>};

